package com.nvv.mediadata.data.model.tmdbimport kotlinx.serialization.SerialNameimport kotlinx.serialization.Serializablesealed interface MediaList<T> {	val page: Int	val results: List<T>	val totalPages: Int	val totalResults: Int}@Serializabledata class RecommendationMovieList(	@SerialName("page")	override val page: Int = 0,	@SerialName("results")	override val results: List<Movie> = emptyList(),	@SerialName("total_pages")	override val totalPages: Int = 0,	@SerialName("total_results")	override val totalResults: Int = 0) : MediaList<Movie>@Serializabledata class RecommendationTVList(	@SerialName("page")	override val page: Int = 0,	@SerialName("results")	override val results: List<TV> = emptyList(),	@SerialName("total_pages")	override val totalPages: Int = 0,	@SerialName("total_results")	override val totalResults: Int = 0) : MediaList<TV>@Serializabledata class Reviews(	@SerialName("page")	override val page: Int = 0,	@SerialName("results")	override val results: List<Review> = emptyList(),	@SerialName("total_pages")	override val totalPages: Int = 0,	@SerialName("total_results")	override val totalResults: Int = 0) : MediaList<Review>